using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using Frociart;
public static class FpgtIntegrationTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Reject(Action action,string why){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(IOException){rejected=true;}Check(rejected,why);}
 static string B(string s){return Convert.ToBase64String(Encoding.UTF8.GetBytes(s));}
 public static int Main(string[] args){try{
  string root=args[0];var rows=new List<string>();var doc=FlowPseudocode.Decode("DICHIARA x: INTERO\nx=2\nSTAMPA x+1");var program=FlowSource.Compile(doc);byte[] before=DiagramIO.EncodeDocument(doc);int models=0;
  foreach(string path in Directory.GetFiles(Path.Combine(root,"references/installed"),"*.fpgt").Concat(Directory.GetFiles(Path.Combine(root,"portable-models"),"*.fpgt")).OrderBy(x=>x,StringComparer.Ordinal)){
   string raw=File.ReadAllText(path);FlowFpgtSyntax syntax;try{syntax=FlowFpgtSyntax.Parse(raw);}catch(FlowFpgtSyntax.SyntaxError){continue;}
   var definition=FlowCodeTemplate.Parse(raw);Check(definition.Base=="flowgorithm"&&definition.Fpgt!=null&&definition.Name==syntax.Name&&definition.FileExtension=="fpgt","Raw model metadata");Check(definition.ExportText==raw.Replace("\r\n","\n").Replace('\r','\n'),"Original sections remain exportable");Check(FlowCodeTemplate.Parse(definition.Text).Text==definition.Text,"Stored wrapper reopens canonically");var code=FlowSourceTarget.FromTemplate("0123456789abcdef0123456789abcdef",definition).Generate(program);Check(code.Text==FlowFpgt.Generate(syntax,program).Text,"Real descriptor uses actual fpgt renderer");rows.Add(Path.GetFileName(path)+"\t"+B(definition.Text)+"\t"+B(code.Text));models++;
  }
  string model=File.ReadAllText(Path.Combine(root,"portable-models/OwnPython.fpgt")).Replace("\r\n","\n");var d=FlowCodeTemplate.Parse(model);var folder=Path.Combine(root,"integration-store",Guid.NewGuid().ToString("N"));var store=new FlowTemplateStore(folder);string id=FlowTemplateStore.NewId();var entry=store.Save(id,d.Text,null);Check(entry.Definition.Base=="flowgorithm","Saved model retains format");string invalid=d.Body.Replace("[Language]","[Language");var draft=new FlowTemplateDraft("Alias","flowgorithm","py","Istruzioni",invalid);store.SaveDraft(id,draft.Encode());Check(FlowTemplateDraft.Decode(store.Load(id).Draft).Body==invalid&&store.Load(id).Definition.Body==d.Body,"Unfinished original-format draft stays separate");Reject(()=>store.Save(id,draft.Definition().Text,entry.Fingerprint),"Invalid raw body cannot replace saved model");Check(store.Load(id).Fingerprint==entry.Fingerprint,"Invalid save preserves exact saved revision");string export=Path.Combine(folder,"copy.fpgt");FlowTemplateStore.Export(export,entry.Definition);Check(FlowCodeTemplate.Parse(FlowTemplateStore.ReadImport(export)).ExportText==d.Body&&!File.ReadAllText(export).Contains("[Frociart Template]"),"External export is a genuine raw fpgt file");store.Archive(id,entry.Fingerprint);store.Restore(id);Check(store.Load(id).Draft==draft.Encode()&&store.Load(id).Definition.Body==d.Body,"Archive/restore retains raw definition and draft");
  var renamed=FlowCodeTemplate.Create("Alias","flowgorithm","txt","Istruzioni",model.Replace("Extension = py","Extension = java"));Check(renamed.Extension=="java"&&renamed.Name=="Alias","Raw metadata drives extension; library alias stays separate");
  foreach(var encoding in new Encoding[]{new UTF8Encoding(false,true),new UTF8Encoding(true,true),new UnicodeEncoding(false,true,true),new UnicodeEncoding(true,true,true)}){byte[] data=encoding.GetPreamble().Concat(encoding.GetBytes(model)).ToArray();string text=FlowCodeTemplate.Decode(data);Check(FlowCodeTemplate.Parse(text).Text==d.Text,"Strict UTF8/UTF16 import");}
  Reject(()=>FlowCodeTemplate.Decode(new byte[]{0xff,0xfe,0x00}),"Truncated UTF16 rejected");Reject(()=>FlowCodeTemplate.Decode(new byte[]{0xff,0xff}),"Invalid UTF8 rejected");
  string padded=model+"\n;";padded+=new string('a',FlowCodeTemplate.MaxCharacters-padded.Length);var boundary=FlowCodeTemplate.Parse(padded);Check(boundary.Body.Length==FlowCodeTemplate.MaxCharacters&&boundary.Text.Length>FlowCodeTemplate.MaxCharacters,"Maximum raw model fits a storage wrapper");string second=FlowTemplateStore.NewId();var large=store.Save(second,FlowCodeTemplate.Create("Grande","flowgorithm","py","",padded).Text,null);Check(large.Definition.Body==padded,"Maximum-size raw body survives durable save");Reject(()=>FlowCodeTemplate.Parse(padded+"x"),"Raw model limit remains enforced");
  var input=FlowPseudocode.Decode("LEGGI x\nSTAMPA x");byte[] inputBefore=DiagramIO.EncodeDocument(input);var target=FlowSourceTarget.FromTemplate("0123456789abcdef0123456789abcdef",d);Reject(()=>target.Generate(FlowSource.Compile(input)),"Unknown input requires an explicit profile");var profile=new Dictionary<string,FlowDataType>{{FlowFpgtTypes.Key(null,"x"),FlowDataType.Integer}};Check(target.GenerateTyped(FlowSource.Compile(input),profile).Text.Contains("int(input())"),"Profile drives actual generated input");Check(inputBefore.SequenceEqual(DiagramIO.EncodeDocument(input))&&before.SequenceEqual(DiagramIO.EncodeDocument(doc)),"All integration paths preserve original diagrams");
  var java=FlowSourceTarget.FromTemplate("0123456789abcdef0123456789abcdef",FlowCodeTemplate.Parse(File.ReadAllText(Path.Combine(root,"portable-models/OwnJava.fpgt"))));Check(java.FileName(java.Generate(program).Text)=="Program.java","Java save name follows public class");Check(java.FileName(new string('\n',40000))=="Programma.java","Blank source filename scan terminates and falls back");Check(java.FileName("public class ../outside")=="Programma.java","Unsafe Java name never becomes a path");
  File.WriteAllLines(Path.Combine(root,"integration-csharp.tsv"),rows,new UTF8Encoding(false));Console.WriteLine("FPGT_INTEGRATION_PC PASS checks="+checks+" models="+models);return 0;
 }catch(Exception error){Console.WriteLine(error);return 1;}}
}
